package main

import (
	"context"
	"fmt"
	"math"
	"sync"
	"time"

	"google.golang.org/grpc"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"
)

// Feature flags controlling rate limiting behavior
type FeatureFlags struct {
	EnableAdaptiveRateLimit bool
	BurstMultiplier         int32
	WindowSeconds           int32
	MaxTokensPerWindow      int32
}

var defaultFlags = FeatureFlags{
	EnableAdaptiveRateLimit: true,
	BurstMultiplier:         3,
	WindowSeconds:           60,
	MaxTokensPerWindow:      1000,
}

// TokenBucket implements a token bucket rate limiter
type TokenBucket struct {
	mu           sync.Mutex
	tokens       int32
	capacity     int32
	refillRate   int32
	lastRefill   time.Time
}

// RateLimitService handles gRPC rate limiting
type RateLimitService struct {
	buckets map[string]*TokenBucket
	mu      sync.RWMutex
	flags   *FeatureFlags
}

func NewRateLimitService(flags *FeatureFlags) *RateLimitService {
	return &RateLimitService{
		buckets: make(map[string]*TokenBucket),
		flags:   flags,
	}
}

// computeEffectiveCapacity calculates the effective token capacity
// based on feature flags and client tier
func (s *RateLimitService) computeEffectiveCapacity(clientTier int32) int32 {
	baseCapacity := s.flags.MaxTokensPerWindow

	if !s.flags.EnableAdaptiveRateLimit {
		return baseCapacity
	}

	// Adaptive rate limiting: scale capacity by tier and burst multiplier
	// Tier 0 = basic, Tier 1 = premium, Tier 2 = enterprise
	tierMultiplier := clientTier + 1

	// Calculate scaled capacity: base * tierMultiplier * burstMultiplier
	// This uses intermediate int32 arithmetic
	scaledByTier := baseCapacity * tierMultiplier
	effectiveCapacity := scaledByTier * s.flags.BurstMultiplier

	return effectiveCapacity
}

// computeRefillRate determines tokens added per second
func (s *RateLimitService) computeRefillRate(capacity int32) int32 {
	if s.flags.WindowSeconds <= 0 {
		return 1
	}
	// Tokens per second to refill the bucket within one window
	rate := capacity / s.flags.WindowSeconds
	if rate < 1 {
		rate = 1
	}
	return rate
}

// getBucket retrieves or creates a token bucket for a client
func (s *RateLimitService) getBucket(clientID string, clientTier int32) *TokenBucket {
	s.mu.RLock()
	bucket, exists := s.buckets[clientID]
	s.mu.RUnlock()

	if exists {
		return bucket
	}

	capacity := s.computeEffectiveCapacity(clientTier)
	refillRate := s.computeRefillRate(capacity)

	bucket = &TokenBucket{
		tokens:     capacity,
		capacity:   capacity,
		refillRate: refillRate,
		lastRefill: time.Now(),
	}

	s.mu.Lock()
	s.buckets[clientID] = bucket
	s.mu.Unlock()

	return bucket
}

// refillTokens adds tokens based on elapsed time
func (b *TokenBucket) refillTokens() {
	now := time.Now()
	elapsed := now.Sub(b.lastRefill)
	tokensToAdd := int32(elapsed.Seconds()) * b.refillRate

	if tokensToAdd > 0 {
		b.tokens += tokensToAdd
		if b.tokens > b.capacity {
			b.tokens = b.capacity
		}
		b.lastRefill = now
	}
}

// TryConsume attempts to consume tokens for a request
func (b *TokenBucket) TryConsume(cost int32) bool {
	b.mu.Lock()
	defer b.mu.Unlock()

	b.refillTokens()

	if b.tokens >= cost {
		b.tokens -= cost
		return true
	}
	return false
}

// RateLimitInterceptor is a gRPC unary interceptor
func (s *RateLimitService) RateLimitInterceptor() grpc.UnaryServerInterceptor {
	return func(
		ctx context.Context,
		req interface{},
		info *grpc.UnaryServerInfo,
		handler grpc.UnaryHandler,
	) (interface{}, error) {
		clientID := extractClientID(ctx)
		clientTier := extractClientTier(ctx)
		requestCost := computeRequestCost(info.FullMethod)

		bucket := s.getBucket(clientID, clientTier)

		if !bucket.TryConsume(requestCost) {
			return nil, status.Errorf(codes.ResourceExhausted,
				"rate limit exceeded for client %s", clientID)
		}

		return handler(ctx, req)
	}
}

// UpdateFlags allows dynamic feature flag updates via admin RPC
func (s *RateLimitService) UpdateFlags(ctx context.Context, newFlags *FeatureFlags) error {
	// Validate flags before applying
	if newFlags.WindowSeconds < 1 || newFlags.WindowSeconds > 3600 {
		return fmt.Errorf("invalid window_seconds: must be 1-3600")
	}
	if newFlags.BurstMultiplier < 1 || newFlags.BurstMultiplier > 100 {
		return fmt.Errorf("invalid burst_multiplier: must be 1-100")
	}
	if newFlags.MaxTokensPerWindow < 1 || newFlags.MaxTokensPerWindow > math.MaxInt32 {
		return fmt.Errorf("invalid max_tokens: must be positive")
	}

	s.flags = newFlags
	// Clear existing buckets to apply new limits
	s.mu.Lock()
	s.buckets = make(map[string]*TokenBucket)
	s.mu.Unlock()

	return nil
}

func extractClientID(ctx context.Context) string {
	// Extract from gRPC metadata in production
	return "default-client"
}

func extractClientTier(ctx context.Context) int32 {
	// Extract from gRPC metadata; validated upstream
	return 0
}

func computeRequestCost(method string) int32 {
	// Different methods have different costs
	return 1
}

func main() {
	svc := NewRateLimitService(&defaultFlags)
	_ = svc
}
